import json, re, html, hashlib
from pathlib import Path

ROOT=Path('/workspace/scratch/f85ae98f1669')
SITE=ROOT/'tmp/batch-engineering/current-site'
LIVE=SITE/'library/data/tzidkat-hatzadik'
BOOKS=SITE/'mcp-data/text'
CACHE=json.loads((ROOT/'review-work/ois76-primary.json').read_text())
CATALOG=json.loads((SITE/'mcp-data/catalog.json').read_text())['books']
CONNECTED=json.loads((SITE/'library/connected-ideas/catalog.json').read_text())['records']
E=[]

def clean(t):
    return re.sub(r'\s+',' ',html.unescape(re.sub('<[^>]*>','',t))).strip()
def plain(t):
    return html.unescape(re.sub('<[^>]*>','',t))
def he(ref,*indices):
    t=CACHE[ref]['he']
    for i in indices:t=t[i-1]
    return re.sub('[\u0591-\u05c7]','',clean(t))
def span(ref,a,b):
    return ' '.join(he(ref,i) for i in range(a,b+1))
def sub(t,start=None,end=None):
    if start:t=t[t.index(start):]
    if end:t=t[:t.index(end)]
    return t.strip()
def row(book,ref):
    return next(x for x in json.loads((BOOKS/f'{book}.json').read_text())['paras'] if x['r']==ref)
def local(book,ref,lo=0,hi=None):
    r=row(book,ref)
    return clean(' '.join(x[0] for x in r['p'][lo:hi]) if 'p'in r else r['t'])
def pg(n,i):return {'neimosA':n,'integratedA':i}
P={76:pg(list(range(210,213)),list(range(247,251))),
   77:pg(list(range(212,216)),list(range(250,254))),
   78:pg(list(range(215,218)),list(range(253,257))),
   79:pg(list(range(218,221)),list(range(256,260))),
   80:pg(list(range(221,225)),list(range(259,264)))}
def add(s,id,pi,ref,h,en,context,anchorEnd=None,url=None,book=None,cacheRef=None,indices=None):
    r=next(x for x in json.loads((LIVE/f'{s-1}.json').read_text()) if x['n']==1)
    full=plain(r['p'][pi][0])
    anchor=full if anchorEnd is None else full[:full.index(anchorEnd)+len(anchorEnd)]
    if book:
        canonical=row(book,ref)
        b=next(x for x in CATALOG if x['slug']==book)
        sectionRef=b['sections'][canonical['s']]['ref']
        url='#/read/'+sectionRef.replace(' ','_')
        assert h in local(book,ref), (ref,'noncontiguous canonical quotation')
    else:url=url or 'https://www.sefaria.org/'+ref.replace(' ','_')
    ev={'ref':ref,'url':url,'he':h,'en':en,
        'translation':'Original English translation prepared directly from the cited Hebrew or Aramaic.',
        'coverage':'Complete selected source unit; all qualifications needed for its meaning retained.',
        'heSha256':hashlib.sha256(h.encode()).hexdigest()}
    if book:
        ev.update(canonicalReaderRef=ref,canonicalSourceFile=f'mcp-data/text/{book}.json',contextHe=local(book,ref))
    if cacheRef:
        ev.update(cacheRef=cacheRef,retrievalURL=CACHE[cacheRef]['retrievalURL'],heVersionTitle=CACHE[cacheRef].get('heVersionTitle'))
    if indices is not None:ev['sourceIndex']=indices
    entry={'section':s,'id':id,'rowN':1,'phraseIndex':pi,'heAnchorPrefix':anchor,'heCharOffset':len(anchor),
        'ref':ref,'url':url,'he':h,'en':en,'context':context,'sourceEvidence':[ev],
        'reviewEvidence':{'pdfPages':P[s],'preserveExisting':True,'status':'verified',
            'dedup':'Compared all native and connected notes in this destination ois. The selected passage is not already quoted there.',
            'method':'Both supplied editions reviewed; original source checked in context; exact current Hebrew anchor verified.'}}
    if book:
        entry['readerRef']=ref
        entry['reviewEvidence']['readerHebrewAlignment']={'canonicalRef':ref,'canonicalHebrewSha256':ev['heSha256'],'existingSourceTextUnchanged':True}
    else:entry['openExternal']=True
    E.append(entry)

# Ois 76: preparation, the proportion of the trial, and the potential within destruction.
add(76,'likkutei-repentance-and-preparatory-failure',0,'Likkutei Maamarim, On Book of Joshua 23',
    local('likkutei-maamarim','Likkutei Maamarim, On Book of Joshua 23',0,12),
    'This is the meaning of repentance, through which deliberate sins become merits: even the stumbling blocks belong to the blessed God’s ordering and prepare for words of Torah. But if someone did not merit repenting during his lifetime, another person then comes to understand the words of Torah that he prepared through his stumbling. This is the meaning of “If he did not merit, he takes his own portion and his fellow’s portion in Gehinnom”—that is, in the stumbling blocks that were fitting for his fellow. His fellow who merits takes his own portion and his fellow’s portion in the Garden of Eden, as explained above concerning Yehoshua and the spies. This is the blessed God’s call, “Return”: coming to understand words of Torah after the stumbling, which is the concealment of the fact that the blessed God is before his eyes and directs him. When he subsequently understands, and the Holy One, blessed be He, returns to him and says that in truth everything is in his hands and comes through his effort, there is then no stumbling at all—for there was no stumbling, since in truth everything is in the person’s hands. This is why the blessed God is called “He who abundantly forgives”: forgiveness comes from His side. But from the human side there must be recognition of sin and deficiency, as it is stated, “My sin is before me always”; although one confessed on this Yom Kippur, one confesses again. For if the person himself recognizes no stumbling, but thinks that everything is his own, like all the nations around him, that is indeed a stumbling. From the person’s side, he must recognize that a person has no power of his own. Thus the days when he walked in darkness, when it was concealed from him that the blessed God gives him the power to achieve, were sin and stumbling. Then the blessed God will say that there was no stumbling, as explained above.',
    'The possibility described here depends on repentance. Rav Tzadok explicitly preserves the person’s recognition of sin and distinguishes it from the divine forgiveness that can transform the past.',book='likkutei-maamarim')
add(76,'likkutei-the-greater-attainment-and-trial',2,'Likkutei Maamarim, On Book of Joshua 16',
    local('likkutei-maamarim','Likkutei Maamarim, On Book of Joshua 16',0,8),
    'Therefore Yehoshua, who was a vessel prepared to give the Land as an inheritance and to lead the generation that inherited it, presumably included within his soul all the holiness of the Land, since his soul included all the souls of the generation, as explained above. [This is why the Sages compared him to the face of the moon: it corresponds to the Oral Torah, which receives from the Written Torah, corresponding to the sun, as is known.] Moshe our teacher therefore feared especially for him. Since no one comes to understand words of Torah without stumbling, and since Moshe saw him attaining the fullest understanding of words of Torah, the greater the subsequent understanding, the greater the preceding stumbling. This is as explained above concerning the exiles. He therefore sought mercy for him in particular.',
    'The parallel states the proportion directly. Its practical expression is Moshe’s prayer that Yehoshua be protected through the trial.',book='likkutei-maamarim')
add(76,'pesachim-torah-sustains-heaven-and-earth',8,'Pesachim 68b:13',
    he('Pesachim 68b',13),
    'Every thirty days Rav Sheshet would review his learning. He would stand leaning against the doorpost and say: “Rejoice, my soul; rejoice, my soul! For you I have studied Scripture; for you I have studied Mishnah.” Is that so? Did Rabbi Elazar not say: “Were it not for Torah, heaven and earth would not endure,” as it is stated, “If not for My covenant day and night, I would not have established the laws of heaven and earth”? At the outset, when a person acts, he acts for his own sake.',
    'This supplies the phrase “were it not for it, etc.” The source places Torah’s sustaining of the world alongside the learner’s own benefit and explains why Rav Sheshet could speak of that personal benefit.',cacheRef='Pesachim 68b',indices=[13],anchorEnd='וְאִלְמָלֵא וְכוּלֵי,')
add(76,'tzidkat-abundant-light-at-the-destruction',11,'Tzidkat HaTzadik 171:1',
    local('tzidkat-hatzadik','Tzidkat HaTzadik 171:1',0,14),
    'There is a place prepared for distress, Heaven forbid, as our Sages say in chapter Chelek concerning Shechem: “A place,” and so forth. So too there is a time, as our Sages say there, “A time,” and as they say concerning an Israelite who has a lawsuit in Av. So too with a soul, as in what our Sages said about Rabbi Elazar ben Pedat and many other cases. But how can it be conceived that this was prepared for evil from the beginning of creation? Is it not written, “From the mouth of the Most High evils do not issue”? In truth, the Sages’ language brings healing: they said “prepared for punishment”—purʿanut, a term related to payment. But “the reward of a mitzvah is not in this world”; here there is only payment for transgressions, unless one merits tasting the fruit of his deeds in this world, or performs one of the mitzvot that bear fruit here. That time, place, and soul are prepared to receive payment for what has been earned. The reason that the reward of a mitzvah is not in this world is that the Holy One, blessed be He, gives His full measure, and this world cannot receive that great abundance of good at all. In that place, time, and soul where the blessed God’s payment and reward flow, the abundance of the flow becomes, Heaven forbid, harmful punishment—as is known concerning the mystery of the breaking of the vessels: their death comes through an excess of light. Thus our Sages said concerning “A person shall not see Me”: at the time of their death they do see. This is why our Sages said that the cherubim were found embracing, although Israel were not doing the Omnipresent’s will: the flow of light was then intensely abundant. That is why Yechezkel merited visions of God. One who truly merits receives the payment of good then; this is the meaning of Mashiach’s birth on the Ninth of Av.',
    'This parallel explains how the same moment can contain destruction and the beginning of redemption. It distinguishes the abundant good from the recipient’s capacity to receive it.',book='tzidkat-hatzadik',anchorEnd='לְבִיאַת מָשִׁיחַ')
midrash90="ויהי נועם ה' אלהינו עלינו אמר לו הקדוש ברוך הוא לשעבר על ידי שנבנה בית המקדש על ידי בשר ודם לפיכך חרב וסילקתי שכינתי אבל לעתיד לבוא אני אבנה אותו ומשרה שכינתי בתוכו ואינו חרב לעולם:"
add(76,'midrash-tehillim-the-enduring-future-temple',11,'Midrash Tehillim 90:19',midrash90,
    '“May the pleasantness of Hashem our God be upon us.” The Holy One, blessed be He, said to him: In the past, because the Temple was built by flesh and blood, it was destroyed and I withdrew My Divine Presence. But in the future I will build it and cause My Divine Presence to dwell within it, and it will never be destroyed.',
    'This is the Midrashic source for the description of the future Temple as enduring forever.',url='https://he.wikisource.org/wiki/מדרש_תהלים_צ')
E[-1]['sourceEvidence'][0]['webRef']='turn63view0'

# Ois 77: the uncited authorities and the specific sources behind the examples.
add(77,'taz-the-comparison-with-moshe',4,"Turei Zahav on Shulchan Arukh, Yoreh De'ah 242:20",
    he("Turei Zahav on Shulchan Arukh, Yoreh De'ah 242:20"),
    '“Because of disrespect.” Beit Yosef wrote: It seems to me that this is why the Gemara says, “Even if Yehoshua son of Nun had said it, I would not obey him,” and does not say, “Even if Moshe had said it.” It appears that he understands the disrespect as directed toward Moshe our teacher: the speaker says, in effect, “If another person were like him,” which is impossible, for it is written, “There has not arisen one like Moshe.” In Maharshal’s work on chapter HaChovel, section 53, he cites the following: It is written in the responsa that if a person quarrels with his fellow and says, “I would not accept it from you even if you were like Moshe our teacher,” he is flogged because of the disrespect. [Maharshal continues:] This is a surprising ruling to me, for it is a customary expression and does not greatly disgrace Moshe our teacher. Moreover, ordinarily the speaker did not intend an insult, but merely expressed his refusal to accept forgiveness or appeasement in exaggerated terms. We therefore do not derive further rulings from such a novelty. Nevertheless, it is fitting to be stringent with him through a Monday–Thursday–Monday fast, so that he will take care with his speech. According to his explanation, someone who says “like Yehoshua” should likewise be flogged, for what difference would there be? But the explanation I gave in Beit Yosef’s name appears more correct, since he brings proof from the Gemara. So too in Yevamot: “Even if he were like Yehoshua son of Nun, I would not give him my daughter.”',
    'The Taz records Beit Yosef’s explanation, Maharshal’s different analysis, and his own preference for Beit Yosef. This is the authority behind Rav Tzadok’s reference to “the halakhic authorities”; the quoted discussion preserves the disagreement.',cacheRef="Turei Zahav on Shulchan Arukh, Yoreh De'ah 242:20",anchorEnd='"כְּמֹשֶׁה רַבֵּינוּ עָלָיו הַשָּׁלוֹם"')
add(77,'yoma-the-crown-available-to-everyone',6,'Yoma 72b:6',he('Yoma 72b',6),
    'Rabbi Yochanan said: There are three crowns: that of the altar, that of the Ark, and that of the table. Aharon merited and took the altar’s crown; David merited and took the table’s crown. The Ark’s crown still lies available: whoever wishes to take it may come and take it. Lest you say that it is inferior, Scripture says, “Through me kings reign.”',
    'The Ark’s crown represents Torah. The source gives both elements used in the ois: that this crown remains available to everyone and that kingship itself is associated with Torah.',cacheRef='Yoma 72b',indices=[6],anchorEnd='וְכֶתֶר תּוֹרָה מוּנָּח לַכֹּל,')
add(77,'shemot-rabbah-moshe-and-the-mixed-multitude',7,'Shemot Rabbah 42:6',he('Shemot Rabbah 42:6'),
    '“Go, descend, for your people have acted corruptly.” It does not say “the people,” but “your people.” Moshe said: Master of the world, how are they my people? The Holy One, blessed be He, said to him: They are your people. While they were still in Egypt, I told you, “I shall bring out My hosts, My people.” I told you not to mix a mixed multitude among them. But you, being humble and worthy, said to Me: Those who return are always accepted. I knew what they would ultimately do and told you no, but I fulfilled your wish. They are the ones who made the calf: they worshipped idols, made it, and caused My people to sin. See what is written: it does not say, “These are our gods,” but “These are your gods.” The converts who ascended with Moshe made it and told Israel, “These are your gods.” Therefore the Holy One, blessed be He, said to Moshe: “Go, descend, for your people have acted corruptly.”',
    'The Midrash supplies Moshe’s motive for accepting the mixed multitude and also relates the resulting failure at the calf. Rav Tzadok explains Moshe’s acceptance here through his connection to the crown of Torah.',cacheRef='Shemot Rabbah 42:6')
add(77,'rashi-a-generations-teacher-called-moshe',9,'Rashi on Shabbat 101b:3:1',he('Rashi on Shabbat 101b',3,1),
    '“Moshe”—that is, our teacher in his generation, as Moshe was in his generation.',
    'Rashi explains precisely the sense in which the sage in the Gemara is addressed as “Moshe.” This supplies the interpretation used to distinguish the comparison in the ois.',cacheRef='Rashi on Shabbat 101b',indices=[3,1],anchorEnd='"מֹשֶׁה, שַׁפִּיר קָאָמְרַתְּ"')
add(77,'ran-the-humility-of-poor-scholars',15,'Ran on Nedarim 81a:2:3',he('Ran on Nedarim 81a',2,3),
    '“Be attentive to the children of the poor”—make an effort to teach them Torah, for Torah will emerge from them: they have no other occupation, and, furthermore, they are humble in their own eyes.',
    'The Ran identifies humility as one of the reasons for the saying. This explains the transition from the children of the poor to the image of broken vessels.',cacheRef='Ran on Nedarim 81a',indices=[2,3])
add(77,'zohar-the-king-dwells-in-broken-vessels',16,'Zohar, Yitro 23:11-13',span('Zohar, Yitro 23',11,13),
    'When they reached him [Rabbi Shimon], they found him sitting and studying Torah. He was saying: “A prayer of the poor person when he faints, and before Hashem he pours out his plea.” Every prayer of Israel is a prayer, but the poor person’s prayer is higher than them all. Why? Because it rises to the King’s throne of glory and becomes a crown upon His head. The Holy One, blessed be He, is indeed praised through that prayer. The poor person’s prayer is called “prayer.” “When he faints”: this wrapping is not the wrapping of a garment, for he has none. Rather, here it is written, “when he faints,” and elsewhere, “those who faint from hunger.” “Before Hashem he pours out his plea”—he complains before his Master, and this is pleasing before the Holy One, blessed be He, because through him the world is sustained when no other sustainers of the world are present. Woe to the one against whom that poor person complains to his Master, for the poor person is closer to the King than all others, as it is written, “When he cries to Me, I will hear, for I am gracious.” As for other people in the world, sometimes He hears and sometimes He does not. Why? Because the King dwells in these broken vessels, as it is written, “With the contrite and humble in spirit,” and “Hashem is close to the brokenhearted,” and “A broken and crushed heart, God, You will not despise.”',
    'The Zohar gives the image of the King dwelling in broken vessels within its teaching about the prayer of the poor and the brokenhearted. Rav Tzadok applies that image to the receptivity needed for Torah.',cacheRef='Zohar, Yitro 23',indices=[11,12,13])
add(77,'gittin-rabbi-meirs-descent-from-a-convert',18,'Gittin 56a:6-7',span('Gittin 56a',6,7),
    '[The Roman ruler] sent Nero Caesar against them. When he came, he shot an arrow toward the east, and it fell in Jerusalem; toward the west, and it fell in Jerusalem; toward the four directions of the heavens, and it fell in Jerusalem. He said to a child: Recite your verse to me. The child said: “I shall place My vengeance against Edom in the hand of My people Israel.” He said: The Holy One, blessed be He, wishes to destroy His house and to wipe His hands on that man [me]. He fled, went and converted, and Rabbi Meir descended from him.',
    'This is the Gemara’s account connecting Rabbi Meir with a convert, which explains why he follows Rabbi Akiva in this series of examples.',cacheRef='Gittin 56a',indices=[6,7],anchorEnd='וְכֵן רַבִּי מֵאִיר')
add(77,'rashi-the-kenites-left-jericho-to-study',19,'Rashi on Judges 1:16:1-2',span('Rashi on Judges 1:16',1,2),
    '“From the City of Palms”—this is Jericho. Its fertile land was given to them to enjoy until the Temple would be built. Whoever’s territory would contain the Temple would take that land, so that all Israel would have a share in the Temple. It was given to Yitro’s descendants for four hundred and forty years. The scholars among them left it and went to Othniel son of Kenaz, who is Yavetz, in the wilderness of Yehudah south of Arad, to study Torah. “He settled with the people”—with the students who sat before him. He had asked the Holy One, blessed be He, to provide him with worthy students, as it is stated, “Yavetz called to the God of Israel,” and He provided him with these pious people.',
    'Rashi explains the move from the City of Palms as leaving the fertile land of Jericho to study with Othniel. This supplies the Torah-learning content of the final example.',cacheRef='Rashi on Judges 1:16',indices=[1,2],anchorEnd='מֵעִיר הַתְּמָרִים,')

# Ois 78: the patriarchal sequence and the expressly limited ten-tribes interpretation.
add(78,'sifrei-the-patriarchs-and-the-removal-of-dross',1,'Sifrei Devarim 312:1',
    sub(he('Sifrei Devarim 312',1),'כך כשבא אברהם','ועדין הדבר'),
    'Thus, when Avraham our father came into the world, dross emerged from him: Yishmael and all the sons of Keturah. When Yitzchak came into the world, dross emerged from him: Esav and all the chiefs of Edom. They became worse than the earlier ones. When Yaakov came, no dross emerged from him; rather, all his sons were born worthy, as it is stated, “Yaakov was a wholehearted man, dwelling in tents.” Through whom does the Omnipresent recognize His portion? Through Yaakov, as it is stated, “For Hashem’s portion is His people; Yaakov is the allotment of His inheritance,” and, “For Yah has chosen Yaakov for Himself.”',
    'This is the Midrashic source for the imagery of dross emerging through the earlier patriarchs’ offspring and for its completion in Yaakov.',cacheRef='Sifrei Devarim 312',indices=[1])
add(78,'divrei-soferim-the-completion-in-yaakov',3,'Divrei Soferim 38:3',
    local('divrei-soferim','Divrei Soferim 38:3',15,30),
    'But the descendants of Yaakov our father can no longer change their name and uproot themselves from the root of Jewish identity. Even if their sins reach the heavens, one remains an Israelite in every respect, and the name Israel is not uprooted from him. This is the root in holiness within all Yaakov’s descendants, for his offspring are complete: there is no dross in the root that comes from him within all his subsequent descendants. Therefore this root of the name Israel, coming from Yaakov our father, remains forever. Esav, however, although born in holiness, still had the choice to uproot himself from this holiness inherited from his forefathers. Although the patriarchs merited that the root of their holiness should be fixed in all their descendants—for through their effort they transformed all their powers to holiness, no evil remained in them at all, and only good can emerge from a good root—they had not yet merited complete offspring until Yaakov. This means that their very essence should be transformed entirely, leaving no possibility of evil, so that their existence should be different from that of other human beings and they could beget only what resembled themselves. Just as a human being is not born from an animal, or an animal from a human being, so a gentile cannot be born from an Israelite, or an Israelite from a gentile. This began with Yaakov, who merited the name Israel for himself and his descendants. Avraham and Yitzchak had not yet had their essence transformed entirely until Yaakov’s birth. Then the promise “Through Yitzchak your offspring shall be called”—but not all of Yitzchak—was fulfilled, and Yishmael and Esav were excluded from being called the offspring of Avraham and Yitzchak. Avraham and Yitzchak were then also completed, so that their offspring were complete, because from then on only Yaakov’s descendants were called and reckoned their offspring.',
    'Rav Tzadok distinguishes the stages before and after Yaakov. The opening qualification is essential: the descendants of Yaakov retain the name Israel despite grave wrongdoing.',book='divrei-soferim')
add(78,'takanat-the-ten-tribes-and-maternal-descent',4,'Takanat HaShavin 15:97',
    local('takanat-hashavin','Takanat HaShavin 15:97',10,14),
    'His decree was fulfilled in the ten tribes who became assimilated among the nations, as they said in Yevamot: “They did not move from there until they made them complete gentiles.” However, he [Hoshea] was speaking about the sinners themselves, as was initially decreed that they should be called “not My people”; there [in the Gemara], however, the reference is to their offspring, as is proved from the verse “For they have begotten foreign children.” There, in Hoshea, Rashi explains this verse: because they married gentile women, whose child has the mother’s status. This is also what Shmuel’s first version there says. Both versions intended the same thing, except that each stated it in reference to a different verse.',
    'In his fuller discussion, Rav Tzadok expressly limits the Talmudic statement to offspring of gentile mothers. He distinguishes this from Hoshea’s proposal concerning the sinners themselves; the passage does not describe the removal of Jewish identity from all sinners.',book='takanat-hashavin')
add(78,'meiri-hezekiahs-concern-and-the-mitzvah',6,'Meiri on Berakhot 10a:3',he('Meiri on Berakhot 10a',3),
    'A person may not set aside the positive commandment of procreation because he suspects that he or his partner will not produce worthy offspring—whether on the basis of something heard, reason, or experience. A person has no standing concerning the secrets of God, as they said: “Why involve yourself with the Merciful One’s hidden matters?” Nevertheless, in choosing a partner he should make the appropriate effort, so that he is seen to intend through the marriage to produce worthy children, as the Sages instructed concerning examining her brothers, marrying the daughter of a Torah scholar, and similar matters.',
    'Meiri preserves both parts of the lesson: uncertainty about future children does not displace the mitzvah, and responsible effort in choosing a partner remains appropriate.',cacheRef='Meiri on Berakhot 10a',indices=[3])

# Ois 79: concealment concerns the communicated light and its reception.
add(79,'kometz-four-forms-of-obscured-sunlight',3,'Kometz HaMinchah 1:19:1',
    local('kometz-haminchah','Kometz HaMinchah 1:19:1',0,5),
    'There are four kinds of impairment of the sun. First: every night, when the sun turns away from us. This corresponds to a head of the court who dies, so that his radiance departs, and who is not properly eulogized to draw forth some measure of that light, as the early authorities wrote concerning eulogies. Second: through a cloud, an intervening screen. This corresponds to a betrothed young woman who cries out with no one to save her: the increase of sexual immorality dulls the heart’s ability to receive light, as the Sages said, and as it is written, “All these abominations … and it became defiled.” A screen is thereby formed. Third: through the moon, which is closer to the sun, receives its influence, and is its brother in giving light, yet obstructs the light. This corresponds to two brothers whose blood is shed together in their dispute with one another. Fourth: through the spots visible to observers, which are a withdrawal of light within the luminary itself. This corresponds to intercourse between males, which the kabbalists wrote causes the withholding of the Divine Presence’s flow: measure for measure, the flow returns to the giver rather than to the Divine Presence that receives it, and light and flow are, as it were, absent from the Divine Presence.',
    'This is the first complete set of correspondences in the parallel; Rav Tzadok then offers further mappings. It shows that he uses “impairment of the sun” broadly for several forms of obscured light, including ordinary night and an intervening screen.',book='kometz-haminchah')
add(79,'machshavot-giving-receiving-and-the-divine-attributes',9,'Machshavot Charutz 9:1',
    local('machshavot-charutz','Machshavot Charutz 9:1',14,31),
    'This is the revelation of the Divine Presence below: to impart great light within people’s hearts and also to receive from them. As is known, the dwelling of the Divine Presence below is a need on high; and as the Sages say, “Israel, as it were, sustain their Father in Heaven.” Every offering is described as a “pleasing fragrance,” and all the mitzvot likewise bring satisfaction before Him. It is stated, “You weaken the Rock who bore you”: through their sins they weaken, Heaven forbid, the power of the heavenly retinue. This is because “more than the calf wishes to nurse, the cow wishes to give milk.” Thus, although she gives, she also receives through giving, since she desires and longs to give. We likewise find that a woman can become betrothed through the benefit she receives by giving to an important person: she enjoys his acceptance, so that his receiving from her is considered her receiving, as stated in the first chapter of Kiddushin. This therefore does not contradict what is said elsewhere: “The mitzvot were given only to refine created beings. What difference does it make to the Holy One, blessed be He, whether one slaughters from the neck,” and so forth? Both are true. Since the blessed God wished thereby to refine created beings so that He could bestow every good upon them, He also receives benefit from them: it is a satisfaction before Him that He spoke and His will was done. Likewise, “If you are righteous, what do you give Him, and what does He take from your hand?” does not contradict this, for the same reason. Furthermore, as is known, service and the deeds of those below truly have no relation to the essence of the blessed Infinite. They relate only to His holy emanation, which is also His essence insofar as He emanated light apprehensible to those below. When it arose in His will to create beings, to reign over and guide them, and for them to recognize His kingship, He necessarily emanated light in measured attributes according to the recipients’ measure. All His names, and all the apprehensions of angels, seraphim, ofanim, prophets, and sages, relate only to the emanated attributes.',
    'This parallel explains why giving can itself be described as receiving and why blocked reception can be termed a defect. It expressly distinguishes the divine attributes accessible to created beings from the infinite divine essence.',book='machshavot-charutz')
add(79,'eikhah-rabbah-strengthening-and-weakening-above',11,'Eikhah Rabbah 1:33',
    sub(he('Eikhah Rabbah 1:33'),'וילכו בלא כח לפני רודף, רבי עזריה','רבי הונא ורבי אחא'),
    '“They went without strength before the pursuer.” Rabbi Azaryah said in the name of Rabbi Yehudah son of Rabbi Simon: When Israel do the Omnipresent’s will, they add strength to the might above, as it is stated, “Through God we shall do valiantly.” When Israel do not do the Omnipresent’s will, they weaken, as it were, the great power above, as it is written, “You weaken the Rock who bore you.” Rabbi Yehudah son of Rabbi Simon said in the name of Rabbi Levi son of Rabbi Tarfon: When Israel do the will of the Holy One, blessed be He, they add strength to the might above, as it is stated, “Now, let the power of Hashem be great.” When they do not do the will of the Holy One, blessed be He, they weaken, as it were, the great power above, and they too go without strength before the pursuer.',
    'The Midrash supplies the language of weakening the heavenly power and also its positive counterpart. Rav Tzadok explains that language through the relation between the light and its recipients.',cacheRef='Eikhah Rabbah 1:33')
add(79,'taanit-the-two-jerusalems',12,'Taanit 5a:11-12',span('Taanit 5a',11,12),
    'Rav Nachman said to Rabbi Yitzchak: What is the meaning of “The Holy One is in your midst, and I shall not enter the city”? Is it because the Holy One is in your midst that He will not enter the city? He answered: Rabbi Yochanan said thus: The Holy One, blessed be He, said, “I shall not enter the Jerusalem above until I enter the Jerusalem below.” Is there a Jerusalem above? Yes, as it is written, “Jerusalem, built as a city joined together.”',
    'The source relates the heavenly Jerusalem to the earthly one. It supplies the background for Rav Tzadok’s language of destruction above accompanying the destruction below.',cacheRef='Taanit 5a',indices=[11,12],anchorEnd='וְזֶהוּ עִנְיַן הַחוּרְבָּן דִּלְעֵילָא,')
add(79,'berakhot-moshes-request-about-the-shekhinah',14,'Berakhot 7a:24',he('Berakhot 7a',24),
    '[Moshe] requested that the Divine Presence should not rest upon idolaters, and it was granted to him, as it is stated, “Let me and Your people be distinguished.”',
    'This is the Talmudic statement invoked in the closing sentence. Rav Tzadok develops its significance for the reception of divine light.',cacheRef='Berakhot 7a',indices=[24],anchorEnd='בְּעוֹבְדֵי כּוֹכָבִים,')

# Ois 80: the three changes, the limited use of severity, and the closing allusions.
add(80,'rosh-hashanah-the-changes-that-tear-up-a-decree',0,'Rosh Hashanah 16b:6-7',span('Rosh Hashanah 16b',6,7),
    'Rabbi Yitzchak said: Four things tear up a person’s decree: charity, crying out, a change of name, and a change of conduct. Charity—as it is written, “Charity rescues from death.” Crying out—as it is written, “They cried to Hashem in their distress, and He brought them out of their straits.” A change of name—as it is written, “Sarai your wife: you shall not call her name Sarai, for Sarah is her name,” and, “I will bless her and also give you a son through her.” A change of conduct—as it is written, “God saw their deeds,” and, “God relented concerning the harm He had said He would bring upon them, and did not do it.” Some say: a change of place as well, for it is written, “Hashem said to Avram: Go forth from your land,” and afterward, “I shall make you a great nation.” The other opinion holds that it was the merit of the Land of Israel that benefited him.',
    'This is the Talmudic framework for the changes of place, conduct, and name developed in the ois. The source includes the alternative explanation of Avraham’s changed circumstances.',cacheRef='Rosh Hashanah 16b',indices=[6,7],anchorEnd='שִׁינּוּי מָקוֹם,')
add(80,'machshavot-holy-severity-is-directed-against-evil',1,'Machshavot Charutz 13:2',
    local('machshavot-charutz','Machshavot Charutz 13:2',30,34),
    'The anger in the liver should be only “the wrath of the Sages, which is good in every respect,” and only where the blessed God commands anger. These are the holy powers of severity, from whose side the Torah emerges; it contains stringent judgments. But all of this is directed against the side of evil, whose root is in the descendants of Amalek. When they are removed from the world, “Israel’s iniquity will be sought and will not be found,” and everything will be good in every respect.',
    'Rav Tzadok expressly limits the “holy powers of severity” to their proper purpose. This clarifies the qualification “which are good” in the Hebrew phrase.',book='machshavot-charutz')
add(80,'makkot-the-protection-of-words-of-torah',2,'Makkot 10a:11-13',span('Makkot 10a',11,13),
    'Rabbi Yochanan said: If a teacher goes into exile, his academy is exiled with him. Is that so? Did Rabbi Yochanan not say: From where do we know that words of Torah provide refuge? For it is stated, “Betzer in the wilderness,” and afterward, “This is the Torah.” There is no difficulty: one statement concerns the time when he is engaged in it, and the other the time when he is not engaged in it. Alternatively, what does “provide refuge” mean? From the Angel of Death. Thus Rav Chisda was sitting and studying in the academy, and the messenger of the Angel of Death could not approach him because his mouth never ceased its study. The messenger went up and sat upon the academy’s cedar tree; the cedar cracked, Rav Chisda fell silent, and the messenger was able to reach him.',
    'The Gemara itself associates Torah with refuge, while preserving two explanations of its protection. Rav Tzadok’s association of the Torah scholar’s holy fervor with the city of refuge has this textual background.',cacheRef='Makkot 10a',indices=[11,12,13])
add(80,'avodah-zarah-no-tyranny-toward-created-beings',4,'Avodah Zarah 3a:12',
    sub(he('Avodah Zarah 3a',12),'שאין הקדוש','ואמאי'),
    'For the Holy One, blessed be He, does not act tyrannically toward His creatures.',
    'The Gemara invokes this principle in explaining the further opportunity offered to the nations. Rav Tzadok applies it here to the corresponding possibility of repair where a particular failing is strong.',cacheRef='Avodah Zarah 3a',indices=[12])
add(80,'mei-hashiloach-the-raven-and-anger',7,'Mei HaShiloach, Volume I, Genesis, Noach 2',
    local('mei-hashiloach','Mei HaShiloach, Volume I, Genesis, Noach 2'),
    '“He sent out the raven, and it went out, going and returning,” and so forth. The raven alludes to anger. Noach wished that the trait of anger should not exist in the world, but the Holy One, blessed be He, showed him that, for the present, this trait is still needed in the world. Sometimes, when an evil desire comes upon a person, he can save himself from it by bringing himself into anger against it. This is the meaning of “going and returning until the waters dried”: until evil desires cease from the world, and then anger too will be abolished, for water signifies desire. A small hint of this began in the Temple, where there was a cubit-high deterrent against ravens, as stated in tractate Middot, chapter 4, mishnah 6.',
    'The passage explains how anger and desire can oppose one another and why the corrective use of anger is temporary. It is a parallel teaching of the author’s teacher; it is not presented as the precise wording of the oral teaching about Gilead.',book='mei-hashiloach')
add(80,'dover-ahabs-attempt-to-justify-the-killing',11,'Dover Tzedek, Miscellany 2:3',
    local('dover-tzedek','Dover Tzedek, Miscellany 2:3',16,25),
    'Thus the Sages said: “Ruddy”—[David] resembled Esav, and so forth; “this one kills with the approval of the Sanhedrin,” and so forth. This proceeds from wisdom, which is the fervor of the Sages. [As I heard concerning the verse “Do you know that Ramoth-gilead is ours?” in relation to “Your hair is like a flock [of goats streaming] from Mount Gilead”: hair signifies judgment and indicates anger and killing, as is known; but from Mount Gilead comes the good form of killing, in accordance with the blessed God’s will. This was Ahab’s purpose in seeking to capture Ramoth-gilead: through this he would know that his killing of the prophets had been forgiven, as it too had been killing in accordance with God’s will. That is why he did not succeed there.] Likewise, Yosef’s killing is to burn the house of Esav, pouring his wrath upon idolaters and not upon Israel, Heaven forbid. Therefore it is said, “He did not choose the tribe of Ephraim”—to endure forever, but only for a time. For this good form of killing is itself only temporary, while idolaters and evil remain. In the future, when everything is good, there will be no need for killing at all; desire, however, will remain even then, as explained above from Midrash HaNeʿelam.',
    'The parallel preserves Ahab’s unsuccessful attempt to establish that his actions had been justified. The surrounding passage distinguishes the Sanhedrin’s judgment from wrongdoing and confines the positive use of severity to the period in which evil remains.',book='dover-tzedek')
add(80,'yoma-repentance-when-the-opportunity-returns',14,'Yoma 86b:8',he('Yoma 86b',8),
    'What is the case of a repentant person? Rav Yehudah said: For example, the opportunity for a transgression came to him a first time and a second time, and he escaped it. Rav Yehudah indicated: with the same woman, at the same period, in the same place.',
    'The original passage supplies the recurring test that Rav Tzadok calls a change of conduct: the person now withstands the kind of opportunity in which he previously failed.',cacheRef='Yoma 86b',indices=[8],anchorEnd='וְנִיצּוֹל הֵימֶנָּה,')
add(80,'taanit-shmuel-and-the-arrival-of-davids-kingship',16,'Taanit 5b:3-7',span('Taanit 5b',3,7),
    'Rav Nachman said to Rabbi Yitzchak: What does “It happened when Shmuel grew old” mean? Was Shmuel so old? He was only fifty-two, for a master said: Death at fifty-two years is the death of Shmuel of Ramah. He answered: Rabbi Yochanan said that old age came suddenly upon him. For it is written, “I regret that I made Shaul king.” Shmuel said before Him: Master of the world, You have equated me with Moshe and Aharon, as it is written, “Moshe and Aharon among His priests, and Shmuel among those who call His name.” Just as the work of Moshe’s and Aharon’s hands was not annulled during their lives, so may the work of my hands not be annulled during my life. The Holy One, blessed be He, said: What shall I do? If Shaul dies, Shmuel will not allow it. If Shmuel dies while young, people will speak against him. If neither Shaul nor Shmuel dies, David’s kingship has already arrived, and one reign does not overlap another’s even by a hair’s breadth. The Holy One, blessed be He, said: I shall bring old age suddenly upon him. This is what is written: “Shaul was sitting in Givah beneath the tamarisk in Ramah.” What has Givah to do with Ramah? It teaches that what caused Shaul to remain in Givah for two and a half years was the prayer of Shmuel of Ramah. Is one person displaced before another? Yes, for Rabbi Shmuel bar Nachmani said in the name of Rabbi Yochanan: What does “Therefore I hewed through the prophets; I killed them by the words of My mouth” mean? It does not say “through their deeds,” but “by the words of My mouth.” Thus one person is displaced before another.',
    'This is the narrative behind the two linked phrases in the ois: one person being displaced for another, and the exact boundary between reigns.',cacheRef='Taanit 5b',indices=[3,4,5,6,7])
add(80,'shabbat-all-israel-are-children-of-kings',19,'Shabbat 111a:3',
    sub(he('Shabbat 111a',3),'החושש במתניו'),
    'One whose loins ache may not anoint them with wine or vinegar, but may anoint them with oil, though not rose oil. Children of kings may anoint their wounds with rose oil, since that is their practice on weekdays. Rabbi Shimon says: All Israel are children of kings.',
    'Rabbi Shimon uses this designation in the Mishnah’s discussion of anointing on Shabbat. Rav Tzadok draws upon the designation to extend the concept of kingship to each individual.',cacheRef='Shabbat 111a',indices=[3])
add(80,'rambam-a-change-of-name-and-a-change-of-self',20,'Mishneh Torah, Repentance 2:4',he('Mishneh Torah, Repentance 2:4'),
    'Among the paths of repentance are that the repentant person constantly cries out before God with tears and supplications, gives charity according to his ability, distances himself greatly from the matter in which he sinned, and changes his name—as if to say: I am another person, and I am not the same person who performed those deeds. He changes all his conduct for the good and the upright path, and goes into exile from his place. For exile atones for sin because it brings him to submit and to become humble and lowly in spirit.',
    'Rambam makes the meaning of the changed name explicit: it expresses the person’s transformed conduct and identity. He also explains the humbling effect of changing place, linking the end of the ois with its opening.',cacheRef='Mishneh Torah, Repentance 2:4')

E.sort(key=lambda e:(e['section'],e['rowN'],e['phraseIndex'],e['heCharOffset']))
reasons={
 76:'Added the distinct original discussions of repentance after failure, the proportion of the trial to later attainment, Torah’s sustaining the world, the influx of light at destruction, and the enduring future Temple. Existing Zohar, Chullin, biblical, Yerushalmi, and Peri Tzadik flood quotations already supply the Flood/Torah and Messiah-birth texts and are preserved.',
 77:'Added the missing Taz discussion with its dispute, the three crowns, Moshe’s acceptance of the mixed multitude with its outcome, Rashi’s explanation of the honorific Moshe, Ran’s humility explanation, the Zohar’s broken-vessel image, Rabbi Meir’s convert ancestry, and Rashi’s explanation of the Kenites’ move to Torah study. Existing Gemara passages, the Machshavot Charutz convert quotation, and Peri Tzadik’s Akiva parallel are preserved.',
 78:'Added the original Sifrei imagery, the patriarchal-stage distinction with the continuing identity of Yaakov’s descendants, the express limitation concerning the ten tribes’ offspring, and Meiri’s full two-sided explanation of Hezekiah’s lesson. Existing Ramban, Gemara, Rashi, Tanchuma, Poked Akarim, and Mei HaShiloach quotations already cover the other explicit citations and remain unchanged.',
 79:'Added the resolved Kometz 1:19 passage, Machshavot Charutz’s explanation with its divine-essence qualification, the original Midrash’s two-sided strengthening/weakening teaching, the Talmudic heavenly-Jerusalem passage, and Moshe’s request concerning the Divine Presence. Existing Pesachim, Avodah Zarah, Kometz 1:18, and Peri Tzadik Chanukah passages are preserved.',
 80:'Added the Talmudic framework of changes with the dissent concerning place; the limited use of holy severity; both explanations of Torah’s protection; the no-tyranny principle; the raven/anger teaching; Ahab’s failed inference with its surrounding limits; the recurring test of repentance; the Shmuel/David narrative; Rabbi Shimon’s children-of-kings statement; and Rambam’s changed-identity explanation. Existing native citations and the Sod Yesharim and Peri Tzadik connections remain unchanged.'
}
